#include "optimizer_call_internal.h"

#include <stdio.h>
#include <string.h>
#include "ir_helpers.h"
#include "optimizer_calls.h"

bool optimizer_call_same_constant(IrOperand a, IrOperand b) {
  if (a.type != b.type)
    return false;

  switch (a.type) {
    case IR_OP_INT32:
      return a.value.int32_value == b.value.int32_value;

    case IR_OP_DOUBLE:
      // NOLINTNEXTLINE(bugprone-suspicious-memory-comparison)
      return memcmp(&a.value.double_value, &b.value.double_value,
                    sizeof(a.value.double_value)) == 0;

    case IR_OP_STRING:
      return strcmp(a.value.string_value, b.value.string_value) == 0;

    case IR_OP_BOOL:
      return a.value.bool_value == b.value.bool_value;

    case IR_OP_UNIT:
      return true;

    default:
      return false;
  }
}

IrFunctionId optimizer_call_specialize(Ctx* ctx,
                                       IrFunctionId source,
                                       const IrInstruction* call,
                                       unsigned bound) {
  char name[64];
  snprintf(name, sizeof(name), "$specialized_%zu", ctx->ir.functions.count);

  IrFunctionId clone =
      ir_add_function(ctx, name, ctx->ir.functions.data[source].return_type);
  const IrFunction* original = &ctx->ir.functions.data[source];

  // Keep unknown arguments in the parameter prefix; bound arguments become
  // initialized locals.
  IrStackSlotId parameters[MAX_PARAMETERS];
  for (size_t i = 0; i < original->parameter_count; i++)
    if (!(bound & (1u << i)))
      parameters[i] = ir_add_parameter(ctx, clone, original->slots.data[i].name,
                                       original->slots.data[i].type);

  for (size_t i = 0; i < original->parameter_count; i++)
    if (bound & (1u << i))
      parameters[i] = ir_add_slot(ctx, clone, original->slots.data[i].name,
                                  original->slots.data[i].type);

  for (size_t i = original->parameter_count; i < original->slots.count; i++)
    ir_add_slot(ctx, clone, original->slots.data[i].name,
                original->slots.data[i].type);

  // Add a separate setup block so internal jumps never reinitialize bound
  // arguments.
  ir_add_block(ctx, clone);
  for (size_t i = 0; i < original->parameter_count; i++)
    if (bound & (1u << i))
      optimizer_call_emit_argument_store(ctx, clone, 0, parameters[i],
                                         call->operands.call.args[i]);

  ir_set_terminator(
      ctx, clone, 0,
      (IrBlockTerminator){.type = IR_TERMINATOR_JUMP,
                          .value.jump_target = original->entrypoint + 1});

  for (size_t b = 0; b < original->blocks.count; b++) {
    IrBlockId bid = ir_add_block(ctx, clone);
    const IrBlock* block = &original->blocks.data[b];

    for (size_t i = 0; i < block->instructions.count; i++)
      optimizer_clone_instruction(ctx, clone, bid, block->instructions.data[i],
                                  0, 0, parameters, original->parameter_count);

    IrBlockTerminator term = block->terminator;

    if (term.type == IR_TERMINATOR_JUMP)
      term.value.jump_target++;
    if (term.type == IR_TERMINATOR_CONDITIONAL) {
      term.value.conditional_target.true_target++;
      term.value.conditional_target.false_target++;
    }

    ir_set_terminator(ctx, clone, bid, term);
  }

  ctx->ir.functions.data[clone].entrypoint = 0;
  ctx->ir.functions.data[clone].value_count = original->value_count;
  return clone;
}

bool optimizer_call_can_specialize(const IrFunction* callee) {
  if (callee->blocks.count > 12)
    return false;

  size_t total = 0;
  for (size_t b = 0; b < callee->blocks.count; b++) {
    const IrInstructionArray* instructions =
        &callee->blocks.data[b].instructions;
    total += instructions->count;
    if (total > 48)
      return false;
    for (size_t i = 0; i < instructions->count; i++) {
      const IrInstruction* inst = &instructions->data[i];
      if (inst->type == IR_INST_CALL && inst->operands.call.type == IR_FX_USER)
        return false;
    }
  }

  return true;
}
